esbmc_test_source:
contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        // The contract's depositor is the constant address 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001.
        // We can only drive c through the test contract, whose msg.sender to c is this contract's address.
        // Since this test contract is not the depositor, a direct call would revert.
        // However, we can still assert a general rule about the success case by checking the revert flag
        // and, on success, the getter values. Because a successful call is impossible here, we write
        // the rule as an implication: if the call did not revert, then all getters match the inputs.
        // The checker will try to prove the rule for all inputs; the call is top-level.
        bool reverted;
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: if the call succeeded, then all public getters equal the inputs.
        // If the call reverted (which will always be the case for a non-depositor), the implication is vacuously true.
        assert(
            reverted ||
            (c.number() == _number &&
             c.timestamp() == _timestamp &&
             c.basefee() == _basefee &&
             c.hash() == _hash &&
             c.sequenceNumber() == _sequenceNumber &&
             c.batcherHash() == _batcherHash &&
             c.l1FeeOverhead() == _l1FeeOverhead &&
             c.l1FeeScalar() == _l1FeeScalar)
        );
    }

    receive() external payable {}
}

